activation_collect_dg_sound.statement:
\<lbrakk>routed_context \<kappa> S \<gamma>\<^sub>D\<^sub>G g buffer_key
          global_of route bot0.0 d\<^sub>0 g\<^sub>0 sigma vars x0.0 sg seed
          resolve is_bot \<gamma>\<^sub>M adm;
 (cfg_entry g, c\<^sub>0) \<in> vars;
 S0.0 \<subseteq> \<gamma>\<^sub>D\<^sub>G d\<^sub>0 e\<^sub>0;
 e\<^sub>0 \<le> genv global_of sigma\<rbrakk>
\<Longrightarrow> \<A>\<^bsub>\<kappa>,adm,c\<^sub>0,g,S0.0\<^esub> v c
                  \<subseteq> \<gamma>\<^sub>M (sg (Inl (v, c)))

cstep_preserves_activation_trace_repr.statement:
\<lbrakk>gwf_compile_input vars ReturnVar is_global \<Pi> ps;
 \<kappa>,compile_prog \<Pi> ps \<turnstile> cf \<rightarrow>\<^sub>c cf';
 activation_trace_repr \<kappa> (compile_prog \<Pi> ps) S cf t\<rbrakk>
\<Longrightarrow> \<exists>t'.
                     activation_trace_repr \<kappa> (compile_prog \<Pi> ps)
                      S cf' t'

ls_channel_sound.statement:
\<lbrakk>sound_local_spec \<kappa> \<gamma>\<^sub>c c;
 s \<in> \<gamma>\<^sub>c x\<rbrakk>
\<Longrightarrow> eval_query.channel_holds (ls_channel c x) s

run_voblint_arithmetic_safe.statement:
\<lbrakk>run_voblint conf ds p = Analysed res; SAFE res v;
 s \<in> reaching ds p v; (v, a, w) \<in> intra (elab_cfg p ds);
 e \<in> set (edge_expressions a);
 ob \<in> set (arith_obligations e)\<rbrakk>
\<Longrightarrow> s \<Turnstile> ob
\<lbrakk>run_voblint conf ds p = Analysed res; SAFE res v;
 s \<in> reaching ds p v; (v, ca, ce, k) \<in> calls (elab_cfg p ds);
 e \<in> set (ce_args ca); ob \<in> set (arith_obligations e)\<rbrakk>
\<Longrightarrow> s \<Turnstile> ob
\<lbrakk>run_voblint conf ds p = Analysed res; SAFE res v;
 s \<in> reaching ds p v; (u, ca, ce, k) \<in> calls (elab_cfg p ds);
 ce_dst ca = Some x;
 (v, EA_Ret (Some e) (callee_of_entry ce), w) \<in> intra (elab_cfg p ds);
 \<not> ik_widens (exp_kind e) (kenv_of ds x)\<rbrakk>
\<Longrightarrow> eval e s \<in> ik_range (kenv_of ds x)
\<lbrakk>run_voblint conf ds p = Analysed res; SAFE res v;
 s \<in> reaching ds p v;
 (v, EA_Special (gspecial_call.Min e1.0 e2.0) x, w)
 \<in> intra (elab_cfg p ds);
 \<not> (ik_widens (exp_kind e1.0) (kenv_of ds x) \<and>
         ik_widens (exp_kind e2.0) (kenv_of ds x))\<rbrakk>
\<Longrightarrow> min (eval e1.0 s) (eval e2.0 s)
                  \<in> ik_range (kenv_of ds x)
\<lbrakk>run_voblint conf ds p = Analysed res; SAFE res v;
 s \<in> reaching ds p v;
 (v, EA_Special (gspecial_call.Max e1.0 e2.0) x, w)
 \<in> intra (elab_cfg p ds);
 \<not> (ik_widens (exp_kind e1.0) (kenv_of ds x) \<and>
         ik_widens (exp_kind e2.0) (kenv_of ds x))\<rbrakk>
\<Longrightarrow> max (eval e1.0 s) (eval e2.0 s)
                  \<in> ik_range (kenv_of ds x)
